def restore_original_failure_cause(text,kind):
    pin=P75_FAILURE_CAUSE_INVERSES[kind]
    assert hashlib.sha256(text.encode()).hexdigest()==pin['candidate_sha256']
    for remove,restore in pin['pairs']:
        assert text.count(remove)==1
        text=text.replace(remove,restore,1)
    assert hashlib.sha256(text.encode()).hexdigest()==pin['baseline_sha256']
    return text

